// resolveOffset: reads an overlay's stand-off token as the NUMBER of pixels React Aria's `offset`
// takes, since no `var()` can reach that prop. Shared by the two overlays that hang off a trigger,
// Popover and Tooltip, each passing its own Cmp custom property.
//
// A literal is wrong for anyone who raises their font size: at a 16 / 20 / 24px root font size
// `space.x-small` resolves to 8 / 10 / 12px, while a literal would hold the panel flat.
//
// A READ, never a probe element. A probe appended to measure used pixels is a DOM mutation during
// render: React double-invokes render under StrictMode and gives no ordering guarantee for it under
// concurrent features. `getComputedStyle` on the root returns the custom property already
// substituted, so the only thing left is the unit, and `rem` and `px` are the two the token system
// emits (Ref space is authored in rem). Anything else falls back rather than guessing, as does a
// missing document (SSR) or an unresolvable property.
const OFFSET_FALLBACK = 8;

export function resolveOffset(property: string): number {
  if (typeof document === "undefined") return OFFSET_FALLBACK;
  const root = document.documentElement;
  const raw = getComputedStyle(root).getPropertyValue(property).trim();
  const value = Number.parseFloat(raw);
  if (!Number.isFinite(value) || value <= 0) return OFFSET_FALLBACK;
  if (raw.endsWith("px")) return value;
  if (raw.endsWith("rem")) {
    const rem = Number.parseFloat(getComputedStyle(root).fontSize);
    return Number.isFinite(rem) && rem > 0 ? value * rem : OFFSET_FALLBACK;
  }
  return OFFSET_FALLBACK;
}
